#include <cstdio>
#include <vector>
#include <queue>
#include <string>
#include <sstream>
#include <iostream>

struct Item {
    long long val;
    int arr, idx;
    bool operator>(const Item& o) const { return val > o.val; }
};

int main() {
    int k;
    scanf("%d", &k);
    getchar();
    std::vector<std::vector<long long>> arrs(k);
    for (int i = 0; i < k; ++i) {
        std::string line;
        std::getline(std::cin, line);
        std::istringstream iss(line);
        long long v;
        while (iss >> v) arrs[i].push_back(v);
    }

    std::priority_queue<Item, std::vector<Item>, std::greater<Item>> pq;
    for (int i = 0; i < k; ++i)
        if (!arrs[i].empty()) pq.push({arrs[i][0], i, 0});

    std::vector<long long> out;
    while (!pq.empty()) {
        Item it = pq.top(); pq.pop();
        out.push_back(it.val);
        int ni = it.idx + 1;
        if (ni < (int)arrs[it.arr].size())
            pq.push({arrs[it.arr][ni], it.arr, ni});
    }
    for (size_t i = 0; i < out.size(); ++i) {
        if (i) printf(" ");
        printf("%lld", out[i]);
    }
    printf("\n");
    return 0;
}
